from dataclasses import dataclass, field
from decimal import Decimal

from shop.money import round_cents

VAT_RATES = {"standard": Decimal("0.19"), "reduced": Decimal("0.07")}


@dataclass(frozen=True)
class LineItem:
    sku: str
    name: str
    unit_price: Decimal  # net
    quantity: int
    vat_class: str = "standard"

    def net(self) -> Decimal:
        return self.unit_price * self.quantity

    def vat(self) -> Decimal:
        # Our tax advisor requires VAT to be rounded per line, not on the order total.
        return round_cents(self.net() * VAT_RATES[self.vat_class])


@dataclass
class Order:
    number: str
    customer_name: str
    customer_email: str
    items: list[LineItem] = field(default_factory=list)
    shipping: Decimal = Decimal("0")  # gross, no VAT split


def net_total(order: Order) -> Decimal:
    return sum((item.net() for item in order.items), Decimal("0"))


def vat_total(order: Order) -> Decimal:
    return sum((item.vat() for item in order.items), Decimal("0"))


def gross_total(order: Order) -> Decimal:
    return net_total(order) + vat_total(order) + order.shipping

from decimal import Decimal

from shop.emails import confirmation_body, is_sendable, subject
from shop.orders import LineItem, Order


def make_order(**overrides):
    defaults = dict(
        number="A-1001",
        customer_name="Erika Mustermann",
        customer_email="erika@example.com",
        items=[LineItem("BK-1", "Clean Code", Decimal("30.00"), 1, "reduced")],
    )
    return Order(**{**defaults, **overrides})


def test_subject_contains_order_number():
    assert subject(make_order()) == "Ihre Bestellung A-1001 ist eingegangen"


def test_body_greets_customer_and_lists_items():
    body = confirmation_body(make_order())
    assert body.startswith("Hallo Erika Mustermann,\n")
    assert "  1 x Clean Code\n" in body


def test_order_without_email_is_not_sendable():
    assert not is_sendable(make_order(customer_email=""))

